mapper.select:
SELECT so.shipment_no, i.item_name, sku.sku_name, sod.quantity, sod.unit_price, so.create_time shipmentTime, w.warehouse_name, so.shipment_status, so.recipient, so.remark FROM wms_shipment_order_detail sod LEFT JOIN wms_shipment_order so ON so.id = sod.shipment_id LEFT JOIN wms_item_sku sku on sod.sku_id=sku.id LEFT JOIN wms_item i on i.id=sku.item_id LEFT JOIN wms_warehouse w on w.id = so.warehouse_id
and so.shipment_no like concat('%', #{dto.shipmentNo}, '%')
and so.recipient like concat('%', #{dto.recipient}, '%')
and so.opt_type = #{dto.optType}
and so.warehouse_id = #{dto.warehouseId}
and so.shipment_status = #{dto.shipmentStatus}
and so.create_time >= #{dto.startTime}
and so.create_time <= #{dto.endTime}
